INSERT INTO researchers (id, added_by, name, institution, country, orcid_id, h_index, total_citations, google_scholar_url) VALUES ('2b135f64-20ec-55c2-ab69-a7bf4e01d050', '11111111-1111-1111-1111-111111111111', 'Carlos Campos', 'University of Zaragoza', 'Spain', '0000-0003-1284-9023', 38, 16000, 'https://scholar.google.com/citations?user=campos') ON CONFLICT (orcid_id) DO NOTHING;
INSERT INTO papers (id, user_id, field_id, title, abstract, authors, publication_year, venue, doi, arxiv_id, url, methodology, reading_status, importance_score) VALUES ('06ff0f8f-dcb5-5822-8307-79a7b03b8180', '11111111-1111-1111-1111-111111111111', '12303544-bce5-5f11-8885-a219b6025dbc', 'Attention Is All You Need', 'The dominant sequence transduction models are based on complex recurrent or convolutional neural networks that include an encoder and a decoder. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Experiments on two machine translation tasks show these models to be superior in quality while being more parallelizable and requiring significantly less time to train.', '[{"name": "Ashish Vaswani"}, {"name": "Noam Shazeer"}, {"name": "Niki Parmar"}, {"name": "Jakob Uszkoreit"}, {"name": "Llion Jones"}, {"name": "Aidan N. Gomez"}, {"name": "Lukasz Kaiser"}, {"name": "Illia Polosukhin"}]'::jsonb, 2017, 'NeurIPS 2017 (31st Conference on Neural Information Processing Systems)', '10.48550/arXiv.1706.03762', '1706.03762', 'https://arxiv.org/abs/1706.03762', 'Scaled Dot-Product Attention combined with Multi-Head Attention mechanisms, sinusoidal positional encodings, and encoder-decoder feed-forward stacks.', 'ANALYZED', 10) ON CONFLICT DO NOTHING;
INSERT INTO papers (id, user_id, field_id, title, abstract, authors, publication_year, venue, doi, arxiv_id, url, methodology, reading_status, importance_score) VALUES ('1ae382d1-8fb9-558c-969f-ae9bb7132b81', '11111111-1111-1111-1111-111111111111', '12303544-bce5-5f11-8885-a219b6025dbc', 'Deep Residual Learning for Image Recognition', 'Deeper neural networks are more difficult to train. We present a residual learning framework to ease the training of networks that are substantially deeper than those used previously. We explicitly reformulate the layers as learning residual functions with reference to the layer inputs, instead of learning unreferenced functions. We provide comprehensive empirical evidence showing that these residual networks are easier to optimize, and can gain accuracy from considerably increased depth.', '[{"name": "Kaiming He"}, {"name": "Xiangyu Zhang"}, {"name": "Shaoqing Ren"}, {"name": "Jian Sun"}]'::jsonb, 2016, 'IEEE Conference on Computer Vision and Pattern Recognition (CVPR 2016)', '10.1109/CVPR.2016.90', '1512.03385', 'https://arxiv.org/abs/1512.03385', 'Identity shortcut connections bypassing convolutional layer stacks, allowing gradient flow directly through deep architectures without degradation.', 'ANALYZED', 10) ON CONFLICT DO NOTHING;
INSERT INTO papers (id, user_id, field_id, title, abstract, authors, publication_year, venue, doi, arxiv_id, url, methodology, reading_status, importance_score) VALUES ('4110265c-0016-5038-9082-f1e54074cd7a', '11111111-1111-1111-1111-111111111111', '99d7d96c-5316-537c-996f-fa0fd190dde1', 'N-BaIoT—Network-Based Detection of IoT Botnet Attacks Using Deep Autoencoders', 'A massive distributed denial of service attack carried out by the Mirai IoT botnet demonstrated the severe threat posed by compromised smart home devices. We propose N-BaIoT, an anomaly detection method that uses deep autoencoders to detect anomalous network traffic originating from infected IoT devices. The method was evaluated on 9 commercial IoT devices infected with Mirai and BASHLITE.', '[{"name": "Yair Meidan"}, {"name": "Michael Bohadana"}, {"name": "Yael Mathov"}, {"name": "Yisroel Mirsky"}, {"name": "Asaf Shabtai"}, {"name": "Dominik Breitenbacher"}, {"name": "Yuval Elovici"}]'::jsonb, 2018, 'IEEE Pervasive Computing, Vol. 17, No. 3', '10.1109/MPRV.2018.03367731', '', 'https://ieeexplore.ieee.org/document/8443360', 'Statistical feature extraction over 5 temporal decay windows (100ms, 500ms, 1.5s, 10s, 1min) calculating packet jitter, bandwidth, and protocol counts, evaluated via autoencoder reconstruction error thresholds.', 'ANALYZED', 9) ON CONFLICT DO NOTHING;
INSERT INTO papers (id, user_id, field_id, title, abstract, authors, publication_year, venue, doi, arxiv_id, url, methodology, reading_status, importance_score) VALUES ('cf6ed5f9-cab1-5d52-8923-786356c8e809', '11111111-1111-1111-1111-111111111111', '5a918d50-3ace-5b22-8904-3e996a5c62c0', 'ORB-SLAM3: An Accurate Open-Source Library for Visual, Visual-Inertial, and Multimap SLAM', 'ORB-SLAM3 is the first system able to perform visual, visual-inertial, and multimap SLAM with monocular, stereo, and RGB-D cameras, using pin-hole and fisheye lens models. The main novelty is an Atlas system that manages a multi-map representation allowing seamless operation during long periods of visual tracking loss.', '[{"name": "Carlos Campos"}, {"name": "Richard Elvira"}, {"name": "Juan J. G\u00f3mez Rodr\u00edguez"}, {"name": "Jos\u00e9 M. M. Montiel"}, {"name": "Juan D. Tard\u00f3s"}]'::jsonb, 2021, 'IEEE Transactions on Robotics (T-RO)', '10.1109/TRO.2021.3075644', '2007.11898', 'https://arxiv.org/abs/2007.11898', 'Fast ORB feature tracking combined with continuous pre-integrated IMU factor graph optimization and DBoW2-based loop closing and multi-map merging.', 'ANALYZED', 9) ON CONFLICT DO NOTHING;
INSERT INTO papers (id, user_id, field_id, title, abstract, authors, publication_year, venue, doi, arxiv_id, url, methodology, reading_status, importance_score) VALUES ('d0a7d8c9-1192-54f7-b023-9586ba22dcfe', '11111111-1111-1111-1111-111111111111', 'd3a28ce6-ccc6-520f-8848-dfe3ee56ce55', 'Deep Learning for Radio Frequency Fingerprinting of IoT Devices', 'Radio Frequency Fingerprinting (RFF) exploits tiny hardware imperfections in transmitters to identify wireless devices uniquely at the physical layer. This paper presents ORACLE, an optimized radio classification framework using convolutional networks on raw I/Q signal samples, achieving >99% classification accuracy across 100 commercial off-the-shelf devices.', '[{"name": "Sanket Sankhe"}, {"name": "Mert Cetinkaya"}, {"name": "Kaushik Chowdhury"}]'::jsonb, 2020, 'IEEE Transactions on Mobile Computing', '10.1109/TMC.2019.2947919', '', 'https://ieeexplore.ieee.org/document/8878028', 'Time-domain I/Q sampling and channel-independent frequency offset extraction fed into a 1D-CNN classifier.', 'READ', 8) ON CONFLICT DO NOTHING;
INSERT INTO papers (id, user_id, field_id, title, abstract, authors, publication_year, venue, doi, arxiv_id, url, methodology, reading_status, importance_score) VALUES ('2b34ee26-2533-577a-b0ea-bd9b137d2408', '11111111-1111-1111-1111-111111111111', '8f8c0820-4113-5888-8b01-f7673dfcf900', 'Compressed Sensing', 'Suppose x is an unknown vector in R^m and we measure y = A x where y in R^n with n much smaller than m. When x is sparse in a known basis, L1-norm minimization can reconstruct x exactly from far fewer measurements than classical Shannon-Nyquist sampling would require.', '[{"name": "David L. Donoho"}]'::jsonb, 2006, 'IEEE Transactions on Information Theory, Vol. 52, No. 4', '10.1109/TIT.2006.871582', '', 'https://ieeexplore.ieee.org/document/1614066', 'L1 optimization (Basis Pursuit) exploiting Restricted Isometry Property (RIP) of random measurement matrices.', 'ANALYZED', 10) ON CONFLICT DO NOTHING;
INSERT INTO datasets (id, user_id, name, domain, description, size_mb, num_samples, num_features, license, source_url) VALUES ('cb826c3c-7300-5f7d-b515-ae65d5520890', '11111111-1111-1111-1111-111111111111', 'N-BaIoT', 'Cybersecurity / IoT', 'Real traffic data gathered from 9 commercial IoT devices infected with Mirai and BASHLITE botnets, containing 115 continuous statistical features.', 5400, 7062604, 115, 'CC BY 4.0', 'https://archive.ics.uci.edu/dataset/442/n+baiot+dataset') ON CONFLICT DO NOTHING;
INSERT INTO datasets (id, user_id, name, domain, description, size_mb, num_samples, num_features, license, source_url) VALUES ('6fad81e3-36be-57c1-b8d0-17447c5720fb', '11111111-1111-1111-1111-111111111111', 'CICIoT2023', 'Cybersecurity', 'Extensive modern IoT attack benchmark dataset featuring 33 distinct attack scenarios (DDoS, DoS, Recon, Web, Brute Force, Spoofing, Mirai) across 105 smart devices.', 18000, 46686579, 46, 'Free for Academic Research', 'https://www.unb.ca/cic/datasets/iot-dataset-2023.html') ON CONFLICT DO NOTHING;
INSERT INTO datasets (id, user_id, name, domain, description, size_mb, num_samples, num_features, license, source_url) VALUES ('591059ec-b190-5dd6-a76c-339852c5390b', '11111111-1111-1111-1111-111111111111', 'IoTGeM', 'Physics / IoT Security', 'High-frequency 3-axis geomagnetic anomaly dataset specifically collected for detecting physical enclosure opening, circuit tampering, and magnetic spoofing.', 850, 1250000, 32, 'MIT', 'https://github.com/research/iotgem') ON CONFLICT DO NOTHING;
